void PutFixed64(std::string* dst, uint64_t value) {
    // Append 8 bytes in little-endian order
    dst->reserve(dst->size() + 8);
    for (int i = 0; i < 8; ++i) {
        dst->push_back(static_cast<char>(value & 0xFF));
        value >>= 8;
    }
}

